const input = $('Webhook - Nova pesquisa').first().json.body || {};
const placesResponse = $('Google Places - Buscar empresa').first().json || {};
const place = (placesResponse.places || [])[0];
if (!input.companyName || !String(input.companyName).trim()) throw new Error('Informe companyName no corpo do webhook.');
if (!place) throw new Error('Nenhum estabelecimento foi encontrado no Google Places. Tente informar cidade/estado em location.');
const rawInstagram = $input.first()?.json || {};
const discovery = rawInstagram.business_discovery || null;
const name = place.displayName?.text || input.companyName;
const company = { name, address: place.formattedAddress || '', phone: place.nationalPhoneNumber || '', website: place.websiteUri || '', rating: place.rating ?? null, reviewCount: place.userRatingCount ?? null, googleMapsUrl: place.googleMapsUri || '', categories: place.types || [], description: place.editorialSummary?.text || '', hours: place.regularOpeningHours?.weekdayDescriptions || [] };
const instagramUsername = String(input.instagramUsername || '').replace(/^@/, '');
const instagramUrl = instagramUsername ? 'https://www.instagram.com/' + encodeURIComponent(instagramUsername) + '/' : '';
const template = String(input.templatePrompt || 'Crie uma landing page profissional, mobile-first e acessível para a empresa abaixo. Use somente os dados fornecidos; não invente depoimentos, preços ou serviços. Retorne exclusivamente um documento HTML completo com CSS incluído.');
const replacements = { name: company.name, address: company.address, phone: company.phone, website: company.website, description: company.description, city: input.location || '', services: company.categories.join(', '), mapLink: company.googleMapsUrl, instagram: instagramUrl, rating: company.rating == null ? '' : String(company.rating), reviewCount: company.reviewCount == null ? '' : String(company.reviewCount) };
let prompt = template;
for (const [key, value] of Object.entries(replacements)) { prompt = prompt.replaceAll('${data.' + key + '}', String(value)).replaceAll('{{' + key + '}}', String(value)); }
prompt += '\n\nDados verificados do Google Maps (use sem inventar):\n' + JSON.stringify(company, null, 2);
if (discovery) prompt += '\n\nDados públicos retornados pelo Instagram Business Discovery: ' + JSON.stringify(discovery);
if (instagramUrl) prompt += '\nPerfil Instagram informado: ' + instagramUrl + (discovery ? '' : ' (não foi possível obter dados via API oficial; mantenha apenas o link).');
return [{ json: { mode: input.mode === 'site' ? 'site' : 'prompt', siteName: name, company, instagram: discovery, instagramUrl, prompt } }];

const response = $input.first().json || {};
const source = $('Montar dados e prompt').first().json;
const html = response.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('') || '';
if (!html) throw new Error('Gemini não retornou HTML. Verifique a chave e o limite da API.');
return [{ json: { mode: 'site', siteName: source.siteName, company: source.company, instagram: source.instagram, instagramUrl: source.instagramUrl, html } }];
